class LRUCache {
    class Node { int k,v; Node prev,next; Node(){} Node(int a,int b){k=a;v=b;} }
    Map<Integer,Node> m = new HashMap<>(); int cap,size; Node head,tail;
    LRUCache(int c) { cap=c; head=new Node(); tail=new Node(); head.next=tail; tail.prev=head; }
    int get(int k) { Node n=m.get(k); if(n==null)return -1; mv(n); return n.v; }
    void put(int k,int v) { Node n=m.get(k); if(n==null){ n=new Node(k,v); m.put(k,n); add(n); if(++size>cap){Node t=pop();m.remove(t.k);size--;} }else{n.v=v;mv(n);} }
    void add(Node n) { n.prev=head; n.next=head.next; head.next.prev=n; head.next=n; }
    void rm(Node n) { n.prev.next=n.next; n.next.prev=n.prev; }
    void mv(Node n) { rm(n); add(n); }
    Node pop() { Node r=tail.prev; rm(r); return r; }
}

关键：双向链表+HashMap、虚拟头尾节点避免判空。追问：`LinkedHashMap` 重写 `removeEldestEntry()` 一行搞定。

