class LFUCache {
    class Node { int k,v,freq; Node prev,next; Node(int a,int b){k=a;v=b;freq=1;} }
    class DL { Node head,tail; int size; DL(){head=new Node(0,0);tail=new Node(0,0);head.next=tail;tail.prev=head;}
        void add(Node n){n.prev=head;n.next=head.next;head.next.prev=n;head.next=n;size++;}
        void rm(Node n){n.prev.next=n.next;n.next.prev=n.prev;size--;} Node pop(){Node r=tail.prev;rm(r);return r;} }
    Map<Integer,Node> c=new HashMap<>(); Map<Integer,DL> f=new HashMap<>(); int cap,min;
    LFUCache(int c){cap=c;}
    int get(int k){Node n=c.get(k);if(n==null)return-1;up(n);return n.v;}
    void put(int k,int v){if(cap==0)return;Node n=c.get(k);if(n!=null){n.v=v;up(n);}else{if(c.size()==cap){DL l=f.get(min);c.remove(l.pop().k);}Node nn=new Node(k,v);c.put(k,nn);f.computeIfAbsent(1,x->new DL()).add(nn);min=1;}}
    void up(Node n){int fr=n.freq;DL o=f.get(fr);o.rm(n);if(fr==min&&o.size==0)min++;n.freq++;f.computeIfAbsent(n.freq,x->new DL()).add(n);}
}

关键：freqMap(频次→链表)+minFreq O(1)定位淘汰目标。

