class B { int[] buf; int c,in,out; B(int s){buf=new int[s];}
    synchronized void put(int v) throws Exception { while(c==buf.length) wait(); buf[in]=v; in=(in+1)%buf.length; c++; notifyAll(); }
    synchronized int take() throws Exception { while(c==0) wait(); int v=buf[out]; out=(out+1)%buf.length; c--; notifyAll(); return v; }
}

